import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework._FWOmmqu.js";const u=JSON.parse('{"title":"AI Assistant — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"AI Assistant — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/ai-assistant"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"AI Assistant — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/ai-assistant"}]]},"headers":[],"relativePath":"user-guide/ai-assistant.md","filePath":"user-guide/ai-assistant.md","lastUpdated":1789774219000}'),n={name:"user-guide/ai-assistant.md"};function i(r,e,l,d,c,g){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="ai-assistant-—-user-guide" tabindex="-1">AI Assistant — User Guide <a class="header-anchor" href="#ai-assistant-—-user-guide" aria-label="Permalink to &quot;AI Assistant — User Guide&quot;">​</a></h1><h2 id="who-can-use-it" tabindex="-1">Who can use it <a class="header-anchor" href="#who-can-use-it" aria-label="Permalink to &quot;Who can use it&quot;">​</a></h2><p>Your workspace must have the <strong>AI Assistant</strong> module installed from the Marketplace. Your role needs:</p><ul><li><strong><code>ai.use</code></strong> — chat, Lead Copilot, credit balance</li><li><strong><code>ai.confirm</code></strong> — approve tasks or other suggested writes</li><li><strong><code>ai.manage</code></strong> — configure workspace AI settings (Settings → AI tab and AI settings API)</li></ul><p>Without the module, AI menu items and API routes are hidden.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="business-chat" tabindex="-1">Business chat <a class="header-anchor" href="#business-chat" aria-label="Permalink to &quot;Business chat&quot;">​</a></h3><p>Ask EloSync about your permitted data — open tasks, stale leads, projects, sales pipeline, overdue invoices, and more. Use <strong>Search workspace</strong> (or ask to find a record by name/number) to search across entitled modules in one step. Answers respect your <strong>module entitlements</strong> and <strong>permissions</strong> (for example you only see leads you are allowed to view).</p><p>Off-topic requests (for example logo design, recipes, or external tool recommendations) are declined — EloSync only answers using workspace data and entitled modules.</p><p>On an empty conversation, starter chips appear only when the matching module is installed <strong>and</strong> you have that module’s view permission (<strong>Search workspace</strong> requires the AI module + <code>ai.use</code>). Citations link only to same-app record paths for modules you are entitled to (for example invoices, contacts, help desk, vendors, employees, products, documents, knowledge base, activities, meetings, and other entitled modules).</p><p>Write actions (such as creating a task) appear as <strong>suggestions</strong> first. Nothing is saved until you <strong>confirm</strong>.</p><p>Workspace admins can add <strong>Workspace instructions</strong> under Settings → AI to tune tone and policies; those instructions are included in the assistant’s trusted context.</p><h3 id="lead-copilot" tabindex="-1">Lead Copilot <a class="header-anchor" href="#lead-copilot" aria-label="Permalink to &quot;Lead Copilot&quot;">​</a></h3><p>From a lead record, use Copilot actions:</p><ul><li><strong>Summarize</strong> — status, urgency, and recent activity themes</li><li><strong>Next action</strong> — single best follow-up with rationale</li><li><strong>Draft follow-up</strong> — copy-ready message (general, email, or WhatsApp tone)</li></ul><h3 id="credits-platform-mode" tabindex="-1">Credits (Platform mode) <a class="header-anchor" href="#credits-platform-mode" aria-label="Permalink to &quot;Credits (Platform mode)&quot;">​</a></h3><p>When your workspace uses <strong>Platform AI</strong> (default), each turn consumes credits from:</p><ol><li><strong>Included monthly allowance</strong> (from your AI subscription, prorated when you join mid-month)</li><li><strong>Prepaid packs</strong> (optional Marketplace add-ons — they roll over)</li></ol><p>Check <strong>Settings → AI</strong> or the credits panel for remaining balance. When credits run out, new messages return a payment-required notice until you add a pack or wait for the monthly refresh.</p><h3 id="bring-your-own-key-byok" tabindex="-1">Bring your own key (BYOK) <a class="header-anchor" href="#bring-your-own-key-byok" aria-label="Permalink to &quot;Bring your own key (BYOK)&quot;">​</a></h3><p>If your operator allows it, workspace admins can switch to <strong>BYOK</strong> mode and supply your own provider API key (and optional base URL for Ollama or OpenAI-compatible gateways). Choose from the same provider catalog as Central — OpenAI, Anthropic, Gemini, OpenRouter, Groq, Mistral, DeepSeek, xAI, OpenAI-compatible, and Ollama. OpenRouter and self-hosted providers accept custom model IDs (for example <code>meta-llama/llama-3.3-70b-instruct</code>). Usage is billed by your provider directly; EloSync does not burn platform credits in BYOK mode.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Be specific — mention time ranges (“due today”, “stale 14 days”) for sharper tool use. For “find X”, ask EloSync to search the workspace.</li><li>Confirm write suggestions promptly; pending actions expire after 24 hours.</li><li>Lead Copilot only accesses leads you can already open in the CRM.</li><li>Ask about overdue or due-today tasks, then confirm suggested status changes, assignments, or notes before they apply. Completing or reopening a task still needs the <strong>complete</strong> permission (you do not need <strong>update</strong> just to complete via Ask EloSync).</li><li>With Help Desk installed, ask about open tickets, then confirm suggested status changes, assignments, or notes before they apply.</li><li>With Opportunities installed, ask about a deal or pipeline summary, list pipeline stages, then confirm suggested stage moves, assignments, or notes before they apply.</li><li>With Invoices installed, ask about overdue invoices or a specific invoice, then confirm suggested status changes, assignments, or timeline notes before they apply. Moving to <strong>Unpaid</strong> still needs <strong>send</strong>; cancelling needs <strong>void</strong>. Status suggestions follow the same path as changing status in the app (not the dedicated Send button’s accrual/PDF side effects).</li><li>With Estimates installed, ask about a specific estimate, then confirm suggested status changes, assignments, or timeline notes before they apply. Moving to <strong>Sent</strong> still needs <strong>send</strong>; accepting needs <strong>accept</strong>.</li><li>With Quotations installed, ask about a specific quotation, then confirm suggested status changes, assignments, or timeline notes before they apply. Moving to <strong>Sent</strong> still needs <strong>send</strong>; accepting needs <strong>accept</strong>.</li><li>With Expenses installed, ask about expenses awaiting approval or a specific expense, then confirm suggested status changes, assignments, or notes before they apply. Approving needs <strong>approve</strong>; rejecting needs <strong>reject</strong>; marking paid needs <strong>pay</strong> (and when Accounting is installed, a paid-from account should already be set on the expense — same as changing status in the app without the dedicated Mark as paid dialog).</li><li>With Projects installed, ask about a project or overdue projects, then confirm suggested status changes, assignments, or notes before they apply.</li><li>With Purchase Orders installed, ask about a PO, then confirm suggested status changes, assignments, or notes before they apply. Sending needs <strong>send</strong>; receiving needs <strong>receive</strong>; cancelling needs <strong>cancel</strong>.</li><li>With Payments installed, ask about a payment, then confirm suggested post/void, assignments, or notes before they apply. Posting needs <strong>post</strong>; voiding needs <strong>void</strong> (Ask EloSync cannot move a payment back to draft).</li><li>With Credit Notes installed, ask about a credit note, then confirm suggested issue/apply/void/refund, assignments, or notes before they apply. Issuing needs <strong>issue</strong>; applying needs <strong>apply</strong>; voiding needs <strong>void</strong>; refunding needs <strong>refund</strong> (Ask EloSync cannot move a credit note back to draft).</li><li>With Leave Management installed, ask about a leave request or pending approvals, then confirm suggested <strong>approve</strong> or <strong>reject</strong> before they apply. Both need <strong>approve</strong> permission. Reject always needs review notes; approve may need notes when overriding the default salary deduction. Managers cannot approve their own leave via Ask EloSync (same as the app).</li><li>For leads, confirm suggested assignments or notes before they apply (status changes and Lead Copilot remain available as before). Assigning needs <strong>assign</strong>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/user-guide/tenant-settings">Tenant settings — AI</a></li><li><a href="/user-guide/leads-overview">Leads</a></li><li><a href="/user-guide/tasks-overview">Tasks</a></li><li><a href="/user-guide/projects-overview">Projects</a></li><li><a href="/user-guide/help-desk-overview">Help Desk</a></li><li><a href="/user-guide/opportunities-overview">Opportunities</a></li><li><a href="/user-guide/invoices-overview">Invoices</a></li><li><a href="/user-guide/estimates-overview">Estimates</a></li><li><a href="/user-guide/quotations-overview">Quotations</a></li><li><a href="/user-guide/payments-overview">Payments</a></li><li><a href="/user-guide/credit-notes-overview">Credit Notes</a></li><li><a href="/user-guide/leave-management-overview">Leave Management</a></li><li><a href="/user-guide/purchase-orders-overview">Purchase Orders</a></li><li><a href="/user-guide/expenses-overview">Expenses</a></li></ul>',25)])])}const h=t(n,[["render",i]]);export{u as __pageData,h as default};
